    if (st.tab === "missing") return;
    for (const [id, k] of Object.entries(opts)) $("#" + id).checked = st.opt[st.tab][k];
    if (document.activeElement !== pad) pad.value = st.opt[st.tab].pad;
    pad.placeholder = CARD_DEFAULTS[st.tab].pad;
