start();

content.content:
/* dark by default when the system says so; the header button overrides and is remembered */
:root, :root[data-theme=dark] {
  --bg: #16181c; --panel: #1f2227; --line: #33373e; --text: #e6e6e6; --dim: #9aa0a8; --shade: #16181cb0; --tipbg: #000d;
  --pink: rgb(255, 105, 200); --blue: rgb(0, 140, 255); --accent: #4c8dff; --yes: #2fb344; --no: #e5484d; --warn: #ffc864; --err: #ff7b7b;
  color-scheme: dark;
}
:root[data-theme=light] {
  --bg: #f4f5f7; --panel: #ffffff; --line: #d5d9e0; --text: #1c1f24; --dim: #5f6670; --shade: #f4f5f7c0; --tipbg: #fffffff0;
  --accent: #2f6fe0; --warn: #a86a00; --err: #c62828;
  color-scheme: light;
}
@media (prefers-color-scheme: light) {
  :root:not([data-theme]) {
    --bg: #f4f5f7; --panel: #ffffff; --line: #d5d9e0; --text: #1c1f24; --dim: #5f6670; --shade: #f4f5f7c0; --tipbg: #fffffff0;
    --accent: #2f6fe0; --warn: #a86a00; --err: #c62828;
    color-scheme: light;
  }
}
/* one spacing unit and three radii, used everywhere: panels, controls, chips */
/* a reason's letter keeps its colour from the lab's review sheets; on a light page it is darkened to stay readable */
:root { --ink-amt: 0%; }
:root[data-theme=light] { --ink-amt: 45%; }
@media (prefers-color-scheme: light) { :root:not([data-theme]) { --ink-amt: 45%; } }
.lt, .filter .badge { color: color-mix(in srgb, var(--c), #000 var(--ink-amt)); }
:root { --pad: 12px; --r-panel: 12px; --r-ctl: 8px; --r-chip: 6px; }
* { box-sizing: border-box; }
/* a fixed frame: header, three columns and the footer fill the window; only the columns scroll */
html, body { height: 100%; overflow: hidden; }
body { margin: 0; background: var(--bg); color: var(--text); font: 14px/1.4 system-ui, sans-serif;
  display: grid; grid-template-rows: 52px minmax(0, 1fr) 1cm; }
header { display: flex; gap: 14px; align-items: center; height: 52px; padding: 0 16px; border-bottom: 1px solid var(--line); }
#logo { height: 36px; width: auto; flex: none; }
h1 { font-size: 18px; margin: 0; flex: 1; }
h2 { font-size: 15px; margin: 0 0 6px; }
.dim { color: var(--dim); }
button, select, input { font: inherit; color: var(--text); background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-ctl); }
button { padding: 5px 12px; cursor: pointer; }
button:not(:disabled):hover { border-color: var(--dim); }
select, input[type=text], input[type=number] { padding: 4px 8px; background: var(--bg); }
input:focus-visible, select:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
button:disabled { opacity: .45; cursor: default; }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
/* Load: a button with a dropdown beside it for where to load from */
.split { display: inline-flex; }
.split > button { border-radius: var(--r-ctl) 0 0 var(--r-ctl); font-weight: 600; padding: 4px 14px; }
.split .menu summary { border-radius: 0 var(--r-ctl) var(--r-ctl) 0; padding: 4px 8px; border-left: 1px solid #ffffff55; height: 100%; }
.split .menu summary.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.split .menu summary.primary::after { color: #fff; content: "▾"; }
.menu .pop.right { left: auto; right: 0; }
.menu .pop .item { text-align: left; border: 0; background: none; padding: 4px 2px; white-space: nowrap; }
.menu .pop .item:not(:disabled):hover { color: var(--accent); }

/* three columns of panels; the gutters between them are the handles that resize the side bars */
#layout { --lw: 320px; --rw: 400px; display: grid; grid-template-columns: var(--lw) var(--pad) minmax(0, 1fr) var(--pad) var(--rw);
  grid-template-rows: minmax(0, 1fr); min-height: 0; }
/* the scrollbar's room is kept even when nothing scrolls, so folding a box never changes the bar's width */
aside { overflow-y: auto; scrollbar-gutter: stable; scrollbar-width: thin; padding: var(--pad); }
#left { padding-right: 0; }
#right { padding-left: 0; }
.gutter { cursor: col-resize; position: relative; }
.gutter::after { content: ""; position: absolute; top: 50%; left: 50%; width: 3px; height: 36px; margin: -18px 0 0 -1.5px; border-radius: 2px; background: var(--line); opacity: 0; transition: opacity .15s; }
.gutter:hover::after, body.resizing .gutter::after { opacity: 1; }
body.resizing { cursor: col-resize; user-select: none; }
.box { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-panel); padding: 14px; }
.box + .box { margin-top: var(--pad); }
.box h2 { margin-bottom: 10px; }
.box select { width: 100%; }
#image-box .sec-head { margin-bottom: 10px; }
#thumb-wrap { position: relative; margin-bottom: 8px; border-radius: var(--r-ctl); overflow: hidden; background: #000; cursor: crosshair; line-height: 0; }
#thumb-wrap[hidden] { display: none; }
#thumb { width: 100%; height: auto; }
#thumb-view { position: absolute; border: 1.5px solid #fff; border-radius: 2px; box-shadow: 0 0 0 1px #0008; pointer-events: none; }
#file-name { margin: 0 0 10px; word-break: break-all; font-size: 13px; }
.layers { display: flex; gap: 14px; font-size: 13px; white-space: nowrap; }
.layers label { display: inline-flex; align-items: center; gap: 5px; cursor: pointer; }
/* a channel's checkbox takes the channel's colour when it is on */
input.ch { width: 15px; height: 15px; margin: 0; cursor: pointer; }
input.ch.r { accent-color: #f33; } input.ch.g { accent-color: #2fb344; } input.ch.b { accent-color: #3d6bff; }
.row { display: flex; justify-content: space-between; gap: 8px; margin-top: 12px; }
#find { flex: 1; font-weight: 600; }
/* settings changed since the last run: a light sweeps across the button */
/* Find Candidates and Load shine while they are the next thing to press */
.shine { position: relative; overflow: hidden; box-shadow: 0 0 10px var(--accent); }
.shine::after { pointer-events: none; content: ""; position: absolute; inset: 0; width: 40%;
  background: linear-gradient(100deg, transparent, #ffffff90, transparent); animation: shine 1.8s ease-in-out infinite; }
@keyframes shine { from { transform: translateX(-120%); } to { transform: translateX(320%); } }
/* folding parts of a box */
details.fold { margin-top: 10px; border-top: 1px solid var(--line); padding-top: 8px; }
details.fold > summary { display: flex; align-items: center; gap: 7px; cursor: pointer; font-size: 13px; font-weight: 600; color: var(--dim); list-style: none; }
details.fold > summary::-webkit-details-marker { display: none; }
/* every fold's arrow: a small triangle pointing right when folded and down when open, centred on its text */
details.fold > summary::before, .box.foldable > .sec-head h2::before { content: ""; flex: none; width: 0; height: 0;
  border-style: solid; border-width: 5px 0 5px 7px; border-color: transparent transparent transparent var(--dim); transition: transform .15s; }
details.fold[open] > summary::before, .box.foldable:not(.folded) > .sec-head h2::before { transform: rotate(90deg); }
#main-params { margin-top: 6px; }
#advanced { margin-top: 10px; font-size: 13px; }
#advanced[open] #detect-params { margin-top: 6px; }
#advanced summary { cursor: pointer; }
#main-params:empty { display: none; }
.sec-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.sec-head h2, .sec-head button { margin: 0; white-space: nowrap; }
.sec-head button { padding: 3px 10px; font-size: 12px; }
button.link { border: 0; background: none; padding: 0; color: var(--accent); font-size: 12px; }
button.link:not(:disabled):hover { text-decoration: underline; }
button.link:disabled { color: var(--dim); }
.hint { color: var(--dim); font-size: 12px; margin: 4px 0 8px; }
.hint.slow { color: var(--warn); margin-bottom: 0; }

/* a filter: switch, letter, title and its own count on one line, what it means below, then its dials */
.filter { background: var(--bg); border: 1px solid var(--line); border-radius: var(--r-ctl); padding: 10px 12px; margin-bottom: 8px; }
.filter.off .desc, .filter.off .param, .filter.off .title { opacity: .45; }
.filter .top { display: flex; gap: 8px; align-items: center; cursor: pointer; }
.filter .top input { margin: 0; accent-color: var(--accent); }
.filter .badge { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; border-radius: var(--r-chip);
  font-weight: 700; font-size: 12px; border: 1px solid color-mix(in srgb, var(--c), #000 var(--ink-amt)); background: color-mix(in srgb, var(--c) 14%, transparent); }
.filter .title { flex: 1; font-weight: 600; font-size: 13px; }
.filter .n { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; cursor: help; font-size: 12px; color: var(--dim); font-variant-numeric: tabular-nums; }
.filter .n svg { width: 13px; height: 13px; }
.filter .n:empty { display: none; }
.filter .desc { color: var(--dim); font-size: 12px; margin: 6px 0 0; }
.param { display: grid; grid-template-columns: 1fr 76px; gap: 2px 8px; align-items: center; margin-top: 6px; font-size: 12px; }
.param .name { grid-column: 1 / 3; color: var(--dim); }
.param .slide { position: relative; }
.param input[type=range] { width: 100%; display: block; }
.param .ours { display: none; position: absolute; top: -3px; bottom: -3px; width: 9px; padding: 0; border: 0; background: none; cursor: pointer;
  left: calc(8px + (100% - 16px) * var(--at) - 4.5px); }
.param .ours::after { content: ""; position: absolute; left: 3.5px; top: 0; bottom: 0; width: 2px; border-radius: 1px; background: var(--warn); }
.param.changed .ours { display: block; }
.param.changed .name { color: var(--warn); }
.param input[type=number] { width: 76px; padding: 2px 6px; background: var(--panel); }
.param.bool { grid-template-columns: 1fr auto; }
.param.bool .name { grid-column: 1; }
.param.text input { grid-column: 1 / 3; padding: 2px 6px; background: var(--panel); }
.help { display: inline-flex; align-items: center; justify-content: center; width: 14px; height: 14px; margin-left: 2px; border-radius: 50%;
  border: 1px solid var(--dim); color: var(--dim); font-size: 10px; font-weight: 700; line-height: 1; cursor: help; vertical-align: 1px; }
.help:hover, .help:focus-visible { color: var(--accent); border-color: var(--accent); outline: none; }
#finder-note { margin: 8px 0 0; }

#view { position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0; margin: var(--pad) 0;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-panel); overflow: hidden; }
.toolbar { display: flex; gap: 10px; align-items: center; height: 52px; padding: 0 var(--pad); border-bottom: 1px solid var(--line); font-size: 13px; }
.toolbar .group { display: flex; gap: 10px; align-items: center; }
.toolbar .grow { flex: 1; }
button.big { padding: 6px 18px; font-size: 14px; font-weight: 600; background: var(--accent); border-color: var(--accent); color: #fff; }
#image-view, #items-view { flex: 1; min-height: 0; display: flex; flex-direction: column; }
#image-view[hidden], #items-view[hidden] { display: none; }
#items-view { overflow-y: auto; padding: var(--pad); }
/* zoom: one rounded segmented control */
.zoom { display: inline-flex; align-items: stretch; border: 1px solid var(--line); border-radius: var(--r-ctl); overflow: hidden; background: var(--panel); }
.zoom button { border: 0; border-radius: 0; background: transparent; width: 32px; font-size: 16px; line-height: 1; padding: 5px 0; }
.zoom button:hover { background: var(--bg); }
#zoom-label { min-width: 44px; text-align: center; align-self: center; font-variant-numeric: tabular-nums; border-left: 1px solid var(--line); border-right: 1px solid var(--line); padding: 5px 0; }
/* the overlay options, folded into one dropdown */
.menu { position: relative; }
.menu summary { list-style: none; cursor: pointer; padding: 5px 12px; border: 1px solid var(--line); border-radius: var(--r-ctl); background: var(--panel); }
.menu summary::-webkit-details-marker { display: none; }
.menu summary::after { content: " ▾"; color: var(--dim); }
.menu .pop { position: absolute; top: calc(100% + 4px); left: 0; z-index: 20; display: flex; flex-direction: column; gap: 8px; min-width: 170px;
  padding: 10px 14px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-ctl); box-shadow: 0 6px 18px #0004; }
.menu .pop label { display: flex; align-items: center; gap: 6px; white-space: nowrap; }
.menu .opt { display: flex; align-items: center; gap: 8px; }
.menu .opt label { flex: 1; }
.menu .opt input[type=range] { width: 80px; }
.menu .opt input[type=color] { width: 26px; height: 22px; padding: 0 2px; }
.menu .pop label.num input { width: 58px; padding: 2px 6px; }
/* each view shows only its own tools */
#view[data-view=image] .for-items, #view[data-view=items] .for-image { display: none; }
.tabs { display: inline-flex; border: 1px solid var(--line); border-radius: var(--r-ctl); overflow: hidden; }
.tabs button { border: 0; border-radius: 0; background: transparent; padding: 5px 14px; }
.tabs button + button { border-left: 1px solid var(--line); }
.tabs button.on { background: var(--accent); color: #fff; }
.tabs span { opacity: .75; font-variant-numeric: tabular-nums; }
button.icon { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px; padding: 0; border-radius: 50%; }
button.icon svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
/* the theme button shows where it goes: a sun in dark mode, a moon in light */
#theme .moon, :root[data-theme=light] #theme .sun { display: none; }
:root[data-theme=light] #theme .moon { display: inline; }
@media (prefers-color-scheme: light) {
  :root:not([data-theme]) #theme .sun { display: none; }
  :root:not([data-theme]) #theme .moon { display: inline; }
}
#scroller { flex: 1; overflow: auto; position: relative; background: var(--bg); cursor: grab; touch-action: none; }
#scroller.dragging, #scroller.dragging #overlay g[data-i] { cursor: grabbing; }
#empty { color: var(--dim); padding: 40px; text-align: center; }
#stage { position: relative; }
#base { image-rendering: pixelated; display: block; }
#overlay { position: absolute; left: 0; top: 0; }
#overlay { --pass-c: var(--pink); --fail-c: var(--blue); --pass-w: 1px; --fail-w: 1px; }
#overlay path { fill: none; vector-effect: non-scaling-stroke; stroke-opacity: .6; }
#overlay .red { stroke-opacity: .45; }
#overlay .pass path { stroke: var(--pass-c); stroke-width: var(--pass-w); }
#overlay .fail path { stroke: var(--fail-c); stroke-width: var(--fail-w); }
#overlay .pass .num { fill: var(--pass-c); }
#overlay .fail .num { fill: var(--fail-c); }
#overlay.no-pass .pass, #overlay.no-fails .fail, #overlay.no-nums .num, #overlay.no-letters .let { display: none; }
/* the selection: a thin white ring, clear of the markings */
#overlay .ring { fill: none; stroke: #fff; stroke-opacity: .9; stroke-width: 1.25; vector-effect: non-scaling-stroke; pointer-events: none; }
#overlay .lines { display: none; }
#overlay .pass .lines { display: inline; }
#overlay.no-lines .pass .lines { display: none; }
#overlay .lines line { stroke: #fff; vector-effect: non-scaling-stroke; stroke-width: 1; }
#overlay .lines line.r { stroke-width: 2; }
#overlay text { paint-order: stroke; stroke: #000; stroke-width: 2px; stroke-opacity: .6; font-family: system-ui, sans-serif; }
#overlay .hit { fill: transparent; cursor: pointer; }
#overlay g[data-i] { cursor: pointer; }
#overlay .forced path { stroke-dasharray: 2 1; stroke-opacity: 1; }
#overlay .red, #overlay .lines { pointer-events: none; }

#list { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: var(--pad); align-items: start; }
.card { background: var(--bg); border: 1px solid var(--line); border-radius: var(--r-ctl); padding: 10px; font-size: 12px; }
.card .crop { position: relative; width: max-content; max-width: 100%; margin: 0 auto 8px; line-height: 0; }
/* a crop narrower than its box shrinks as a whole: its height follows its width */
.card .crop canvas { display: block; image-rendering: pixelated; border-radius: var(--r-chip); max-width: 100%; height: auto; }
.card .marks { position: absolute; left: 0; top: 0; width: 100%; height: 100%; overflow: visible; }
.card .marks line { stroke: #fff; stroke-width: 1; vector-effect: non-scaling-stroke; }
.card .marks line.r { stroke-width: 2.5; }
.card .marks text { fill: #fff; text-anchor: middle; paint-order: stroke; stroke: #000; font-family: system-ui, sans-serif; }
.card .marks text.r { fill: #ffb3b3; }
.card .marks .handle { fill: #fff; stroke: #000; cursor: ew-resize; }
.card .marks .handle.r { fill: #ff6b6b; }
.card .head { display: flex; gap: 6px; align-items: center; margin-bottom: 8px; }
/* the user's verdict: a thumbs up and a thumbs down side by side, quiet until pointed at or chosen */
.card .verdict { margin-left: auto; display: inline-flex; flex: none; border: 1px solid var(--line); border-radius: 999px; overflow: hidden; background: var(--panel); }
.card .verdict button { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 26px; padding: 0;
  border: 0; border-radius: 0; background: transparent; color: var(--dim); transition: background .12s, color .12s; }
.card .verdict button + button { border-left: 1px solid var(--line); }
/* the thumb icon, on the cards and beside each filter's count; the filters' is a thumbs down */
.card .verdict svg, .filter .n svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.card .verdict .down svg, .filter .n svg { transform: rotate(180deg) scaleX(-1); }
.card .verdict .up:hover { color: var(--yes); background: color-mix(in srgb, var(--yes) 14%, transparent); }
.card .verdict .down:hover { color: var(--no); background: color-mix(in srgb, var(--no) 14%, transparent); }
.card .verdict .up.on { color: #fff; background: var(--yes); }
.card .verdict .down.on { color: #fff; background: var(--no); }
.card .verdict button.on svg { fill: #ffffff40; }
/* the go-to button sits on the crop, faint until the pointer is over it */
.card .crop-wrap { position: relative; width: max-content; max-width: 100%; margin: 0 auto 8px; }
.card .crop-wrap .crop { margin: 0; }
.card .goto { position: absolute; top: 5px; right: 5px; width: 26px; height: 26px; padding: 0; display: inline-flex; align-items: center; justify-content: center;
  border-radius: 50%; border: 1px solid #ffffff60; background: #000000a0; color: #fff; opacity: .3; transition: opacity .15s; }
.card .crop-wrap:hover .goto, .card .goto:focus-visible { opacity: 1; }
.card .goto:hover { background: var(--accent); border-color: var(--accent); }
.card .goto svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.card .goto svg .dot { fill: currentColor; stroke: none; }
.card .num { font-weight: 700; }
.card.pass .num { color: var(--pink); } .card.fail .num { color: var(--blue); }
.card .state { color: var(--dim); min-width: 0; }
/* the selected candidate's card in the item views */
.card { cursor: pointer; scroll-margin: var(--pad); }
#selected .card { cursor: default; }
.card.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent), 0 0 14px color-mix(in srgb, var(--accent) 45%, transparent); }
.card .tag { color: var(--warn); margin: -2px 0 4px; }
.card .why { display: flex; flex-wrap: wrap; gap: 4px 10px; margin: 2px 0 6px; }
.card.approved { border-color: var(--yes); }
.card.byyou { border-color: var(--no); }
.card .tag button { font-size: 12px; margin-left: 6px; }
.card button { padding: 2px 8px; font-size: 11px; border-radius: var(--r-chip); }
.card table { width: 100%; border-collapse: collapse; }
.card td:last-child { text-align: right; font-variant-numeric: tabular-nums; }
.card td { color: var(--dim); } .card td:last-child { color: var(--text); }

#selected .card { background: var(--bg); }
.stepper { display: inline-flex; border: 1px solid var(--line); border-radius: var(--r-ctl); overflow: hidden; }
.stepper button { border: 0; border-radius: 0; background: transparent; width: 32px; padding: 2px 0; font-size: 16px; line-height: 1.2; }
.stepper button + button { border-left: 1px solid var(--line); }
.stepper button:not(:disabled):hover { background: var(--bg); }
#selected-box .sec-head { margin-bottom: 10px; }
#downloads { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
#downloads h2 { flex-basis: 100%; margin-bottom: 2px; }
#summary .tbl { overflow-x: auto; }
#summary table { border-collapse: collapse; margin-top: 8px; font-variant-numeric: tabular-nums; font-size: 12px; width: 100%; }
#summary th, #summary td { padding: 4px 4px; text-align: right; border-bottom: 1px solid var(--line); }
#summary th:first-child, #summary td:first-child { text-align: left; }
#summary .hists { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 12px; }
#summary .hist { font-size: 12px; color: var(--dim); }
#summary .hist rect { fill: var(--pink); opacity: .75; }
#summary .reasons { margin-top: 12px; color: var(--dim); font-size: 13px; }

/* the footer: file, counts and timings as sections on the left; progress and the version on the right */
#statusbar { display: flex; align-items: center; gap: 10px; height: 1cm; padding: 0 14px; background: var(--panel); border-top: 1px solid var(--line);
  font-size: 12px; color: var(--dim); white-space: nowrap; overflow: hidden; }
#statusbar .seg { padding-right: 10px; border-right: 1px solid var(--line); }
#statusbar .seg:empty { display: none; }
#statusbar .grow { flex: 1; }
#statusbar b { color: var(--text); font-weight: 600; font-variant-numeric: tabular-nums; }
#sb-file { color: var(--text); font-weight: 600; max-width: 30vw; overflow: hidden; text-overflow: ellipsis; }
#sb-times { font-variant-numeric: tabular-nums; }
#status { overflow: hidden; text-overflow: ellipsis; min-width: 0; }
#status.err { color: var(--err); }
#statusbar .spin { width: 12px; height: 12px; display: none; }
#statusbar .spin.on { display: inline-block; }
#sb-version { padding: 1px 8px; border: 1px solid var(--line); border-radius: var(--r-chip); font-variant-numeric: tabular-nums; }
#sb-version.stale { cursor: pointer; color: var(--bg); background: var(--warn); border-color: var(--warn); font-weight: 600; }

#tip { position: fixed; pointer-events: none; background: var(--tipbg); color: var(--text); border: 1px solid var(--line); border-radius: var(--r-ctl); padding: 8px 10px; font-size: 12px; max-width: 320px; z-index: 10; white-space: pre-line; }

@media (max-width: 1300px) {
  #layout { --lw: 260px; --rw: 300px; }
}

.spin { display: inline-block; width: 14px; height: 14px; border: 2px solid var(--line); border-top-color: var(--pink); border-radius: 50%; animation: spin .8s linear infinite; visibility: hidden; }
.spin.on { visibility: visible; }
.spin.big { width: 44px; height: 44px; border-width: 4px; visibility: visible; }
@keyframes spin { to { transform: rotate(360deg); } }
#busy { position: absolute; inset: 52px 0 0 0; z-index: 5; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; background: var(--shade); color: var(--text); }
#busy[hidden] { display: none; }
#busy-time { color: var(--dim); font-variant-numeric: tabular-nums; }
/* over an image (Find Candidates, or one painting as it downloads) the text sits in a pill below it, and
   Find Candidates sweeps a copier's light bar back and forth over the image */
#scan-light { display: none; }
#busy.scan, #busy.peek { background: none; justify-content: flex-end; padding-bottom: 28px; pointer-events: none; overflow: hidden; }
#busy.scan .spin.big, #busy.peek .spin.big { display: none; }
#busy.scan #busy-text, #busy.scan #busy-time, #busy.peek #busy-text, #busy.peek #busy-time { position: relative; z-index: 1; }
#busy.scan #busy-text, #busy.peek #busy-text { padding: 5px 14px; border-radius: 999px; background: var(--shade); font-weight: 600; font-variant-numeric: tabular-nums; }
#busy.scan #busy-time, #busy.peek #busy-time { margin-top: -6px; padding: 1px 10px; border-radius: 999px; background: var(--shade); color: var(--text); }
#busy.scan #scan-light { display: block; position: absolute; top: 0; bottom: 0; left: -90px; width: 90px; mix-blend-mode: screen;
  background: linear-gradient(90deg, transparent, rgba(150, 255, 190, .10) 30%, rgba(235, 255, 245, .75) 50%, rgba(150, 255, 190, .10) 70%, transparent);
  box-shadow: 0 0 60px 20px rgba(120, 255, 170, .18); animation: copier 2.4s ease-in-out infinite alternate; }
@keyframes copier { from { transform: translateX(0); } to { transform: translateX(calc(100cqw + 90px)); } }
#busy.scan { container-type: inline-size; }
@media (prefers-reduced-motion: reduce) { #busy.scan #scan-light { animation-duration: 8s; } }

/* the Google Drive dialog */
#drive-dlg { width: min(640px, calc(100vw - 32px)); padding: 18px; color: var(--text); background: var(--panel);
  border: 1px solid var(--line); border-radius: var(--r-panel); box-shadow: 0 12px 40px #0006; }
#drive-dlg::backdrop { background: #0007; }
.drive-row { display: flex; gap: 8px; align-items: center; margin-top: 10px; }
.drive-row.end { justify-content: space-between; }
#drive-link { flex: 1; min-width: 0; }
/* every part keeps its size whatever the folder holds, so the dialog stays still while browsing */
#drive-path { margin-top: 10px; font-size: 13px; height: 1.5em; line-height: 1.5em; white-space: nowrap; overflow-x: auto; overflow-y: hidden; }
#drive-list { display: flex; flex-direction: column; height: 300px; overflow-y: auto; margin-top: 6px;
  border: 1px solid var(--line); border-radius: var(--r-ctl); }
#drive-list .item { display: flex; gap: 12px; align-items: baseline; flex: none; text-align: left; border: 0; border-radius: 0; background: none; padding: 6px 10px; }
#drive-list .item .name { flex: 1; min-width: 0; overflow-wrap: anywhere; }
#drive-list .item .meta { color: var(--dim); font-size: 12px; white-space: nowrap; font-variant-numeric: tabular-nums; }
#drive-msg { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#drive-list .item + .item { border-top: 1px solid var(--line); }
#drive-list .item:hover { background: var(--bg); }
#drive-list .item.folder .name::before { content: "📁 "; }
#drive-msg.err { color: var(--err); }

/* a box that folds: its title opens and closes it */
.box.foldable > .sec-head h2 { display: flex; align-items: center; gap: 7px; cursor: pointer; user-select: none; }
.box.foldable.folded > :not(.sec-head) { display: none; }
.box.foldable.folded > .sec-head button { display: none; }

/* missing candidates: the user's marks where the finder proposed nothing, in a colour the image never has */
#overlay .missing-marks { --miss: #ffd400; pointer-events: none; }
#overlay .missing-marks circle { fill: none; stroke: var(--miss); stroke-width: 1.5; stroke-dasharray: 4 3; vector-effect: non-scaling-stroke; }
#overlay .missing-marks text { fill: var(--miss); }
.card.missing { border-color: #ffd40080; }
.card .verdict .remove { font-size: 18px; line-height: 1; color: var(--dim); }
.card .verdict .remove:hover { color: var(--no); background: color-mix(in srgb, var(--no) 14%, transparent); }
#ctx { position: fixed; z-index: 30; display: flex; flex-direction: column; padding: 4px 8px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-ctl); box-shadow: 0 6px 18px #0006; }
#ctx .item { text-align: left; border: 0; background: none; padding: 6px 4px; white-space: nowrap; }
#ctx .item:hover, #ctx .item:focus-visible { color: var(--accent); }
#notice { position: fixed; z-index: 40; max-width: min(360px, calc(100vw - 16px)); background: var(--panel); color: var(--text); border: 1px solid var(--accent);
  border-radius: var(--r-ctl); padding: 12px 14px; box-shadow: 0 8px 24px #0007; display: flex; flex-direction: column; gap: 10px; font-size: 13px; }
#notice[hidden] { display: none; }
#notice p { margin: 0; }
#notice button { align-self: flex-end; }
#ctx[hidden], #card-menu[hidden] { display: none; }

toolUseResult.stdout:
/* dark by default when the system says so; the header button overrides and is remembered */
:root, :root[data-theme=dark] {
  --bg: #16181c; --panel: #1f2227; --line: #33373e; --text: #e6e6e6; --dim: #9aa0a8; --shade: #16181cb0; --tipbg: #000d;
  --pink: rgb(255, 105, 200); --blue: rgb(0, 140, 255); --accent: #4c8dff; --yes: #2fb344; --no: #e5484d; --warn: #ffc864; --err: #ff7b7b;
  color-scheme: dark;
}
:root[data-theme=light] {
  --bg: #f4f5f7; --panel: #ffffff; --line: #d5d9e0; --text: #1c1f24; --dim: #5f6670; --shade: #f4f5f7c0; --tipbg: #fffffff0;
  --accent: #2f6fe0; --warn: #a86a00; --err: #c62828;
  color-scheme: light;
}
@media (prefers-color-scheme: light) {
  :root:not([data-theme]) {
    --bg: #f4f5f7; --panel: #ffffff; --line: #d5d9e0; --text: #1c1f24; --dim: #5f6670; --shade: #f4f5f7c0; --tipbg: #fffffff0;
    --accent: #2f6fe0; --warn: #a86a00; --err: #c62828;
    color-scheme: light;
  }
}
/* one spacing unit and three radii, used everywhere: panels, controls, chips */
/* a reason's letter keeps its colour from the lab's review sheets; on a light page it is darkened to stay readable */
:root { --ink-amt: 0%; }
:root[data-theme=light] { --ink-amt: 45%; }
@media (prefers-color-scheme: light) { :root:not([data-theme]) { --ink-amt: 45%; } }
.lt, .filter .badge { color: color-mix(in srgb, var(--c), #000 var(--ink-amt)); }
:root { --pad: 12px; --r-panel: 12px; --r-ctl: 8px; --r-chip: 6px; }
* { box-sizing: border-box; }
/* a fixed frame: header, three columns and the footer fill the window; only the columns scroll */
html, body { height: 100%; overflow: hidden; }
body { margin: 0; background: var(--bg); color: var(--text); font: 14px/1.4 system-ui, sans-serif;
  display: grid; grid-template-rows: 52px minmax(0, 1fr) 1cm; }
header { display: flex; gap: 14px; align-items: center; height: 52px; padding: 0 16px; border-bottom: 1px solid var(--line); }
#logo { height: 36px; width: auto; flex: none; }
h1 { font-size: 18px; margin: 0; flex: 1; }
h2 { font-size: 15px; margin: 0 0 6px; }
.dim { color: var(--dim); }
button, select, input { font: inherit; color: var(--text); background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-ctl); }
button { padding: 5px 12px; cursor: pointer; }
button:not(:disabled):hover { border-color: var(--dim); }
select, input[type=text], input[type=number] { padding: 4px 8px; background: var(--bg); }
input:focus-visible, select:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
button:disabled { opacity: .45; cursor: default; }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
/* Load: a button with a dropdown beside it for where to load from */
.split { display: inline-flex; }
.split > button { border-radius: var(--r-ctl) 0 0 var(--r-ctl); font-weight: 600; padding: 4px 14px; }
.split .menu summary { border-radius: 0 var(--r-ctl) var(--r-ctl) 0; padding: 4px 8px; border-left: 1px solid #ffffff55; height: 100%; }
.split .menu summary.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.split .menu summary.primary::after { color: #fff; content: "▾"; }
.menu .pop.right { left: auto; right: 0; }
.menu .pop .item { text-align: left; border: 0; background: none; padding: 4px 2px; white-space: nowrap; }
.menu .pop .item:not(:disabled):hover { color: var(--accent); }

/* three columns of panels; the gutters between them are the handles that resize the side bars */
#layout { --lw: 320px; --rw: 400px; display: grid; grid-template-columns: var(--lw) var(--pad) minmax(0, 1fr) var(--pad) var(--rw);
  grid-template-rows: minmax(0, 1fr); min-height: 0; }
/* the scrollbar's room is kept even when nothing scrolls, so folding a box never changes the bar's width */
aside { overflow-y: auto; scrollbar-gutter: stable; scrollbar-width: thin; padding: var(--pad); }
#left { padding-right: 0; }
#right { padding-left: 0; }
.gutter { cursor: col-resize; position: relative; }
.gutter::after { content: ""; position: absolute; top: 50%; left: 50%; width: 3px; height: 36px; margin: -18px 0 0 -1.5px; border-radius: 2px; background: var(--line); opacity: 0; transition: opacity .15s; }
.gutter:hover::after, body.resizing .gutter::after { opacity: 1; }
body.resizing { cursor: col-resize; user-select: none; }
.box { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-panel); padding: 14px; }
.box + .box { margin-top: var(--pad); }
.box h2 { margin-bottom: 10px; }
.box select { width: 100%; }
#image-box .sec-head { margin-bottom: 10px; }
#thumb-wrap { position: relative; margin-bottom: 8px; border-radius: var(--r-ctl); overflow: hidden; background: #000; cursor: crosshair; line-height: 0; }
#thumb-wrap[hidden] { display: none; }
#thumb { width: 100%; height: auto; }
#thumb-view { position: absolute; border: 1.5px solid #fff; border-radius: 2px; box-shadow: 0 0 0 1px #0008; pointer-events: none; }
#file-name { margin: 0 0 10px; word-break: break-all; font-size: 13px; }
.layers { display: flex; gap: 14px; font-size: 13px; white-space: nowrap; }
.layers label { display: inline-flex; align-items: center; gap: 5px; cursor: pointer; }
/* a channel's checkbox takes the channel's colour when it is on */
input.ch { width: 15px; height: 15px; margin: 0; cursor: pointer; }
input.ch.r { accent-color: #f33; } input.ch.g { accent-color: #2fb344; } input.ch.b { accent-color: #3d6bff; }
.row { display: flex; justify-content: space-between; gap: 8px; margin-top: 12px; }
#find { flex: 1; font-weight: 600; }
/* settings changed since the last run: a light sweeps across the button */
/* Find Candidates and Load shine while they are the next thing to press */
.shine { position: relative; overflow: hidden; box-shadow: 0 0 10px var(--accent); }
.shine::after { pointer-events: none; content: ""; position: absolute; inset: 0; width: 40%;
  background: linear-gradient(100deg, transparent, #ffffff90, transparent); animation: shine 1.8s ease-in-out infinite; }
@keyframes shine { from { transform: translateX(-120%); } to { transform: translateX(320%); } }
/* folding parts of a box */
details.fold { margin-top: 10px; border-top: 1px solid var(--line); padding-top: 8px; }
details.fold > summary { display: flex; align-items: center; gap: 7px; cursor: pointer; font-size: 13px; font-weight: 600; color: var(--dim); list-style: none; }
details.fold > summary::-webkit-details-marker { display: none; }
/* every fold's arrow: a small triangle pointing right when folded and down when open, centred on its text */
details.fold > summary::before, .box.foldable > .sec-head h2::before { content: ""; flex: none; width: 0; height: 0;
  border-style: solid; border-width: 5px 0 5px 7px; border-color: transparent transparent transparent var(--dim); transition: transform .15s; }
details.fold[open] > summary::before, .box.foldable:not(.folded) > .sec-head h2::before { transform: rotate(90deg); }
#main-params { margin-top: 6px; }
#advanced { margin-top: 10px; font-size: 13px; }
#advanced[open] #detect-params { margin-top: 6px; }
#advanced summary { cursor: pointer; }
#main-params:empty { display: none; }
.sec-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.sec-head h2, .sec-head button { margin: 0; white-space: nowrap; }
.sec-head button { padding: 3px 10px; font-size: 12px; }
button.link { border: 0; background: none; padding: 0; color: var(--accent); font-size: 12px; }
button.link:not(:disabled):hover { text-decoration: underline; }
button.link:disabled { color: var(--dim); }
.hint { color: var(--dim); font-size: 12px; margin: 4px 0 8px; }
.hint.slow { color: var(--warn); margin-bottom: 0; }

/* a filter: switch, letter, title and its own count on one line, what it means below, then its dials */
.filter { background: var(--bg); border: 1px solid var(--line); border-radius: var(--r-ctl); padding: 10px 12px; margin-bottom: 8px; }
.filter.off .desc, .filter.off .param, .filter.off .title { opacity: .45; }
.filter .top { display: flex; gap: 8px; align-items: center; cursor: pointer; }
.filter .top input { margin: 0; accent-color: var(--accent); }
.filter .badge { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; border-radius: var(--r-chip);
  font-weight: 700; font-size: 12px; border: 1px solid color-mix(in srgb, var(--c), #000 var(--ink-amt)); background: color-mix(in srgb, var(--c) 14%, transparent); }
.filter .title { flex: 1; font-weight: 600; font-size: 13px; }
.filter .n { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; cursor: help; font-size: 12px; color: var(--dim); font-variant-numeric: tabular-nums; }
.filter .n svg { width: 13px; height: 13px; }
.filter .n:empty { display: none; }
.filter .desc { color: var(--dim); font-size: 12px; margin: 6px 0 0; }
.param { display: grid; grid-template-columns: 1fr 76px; gap: 2px 8px; align-items: center; margin-top: 6px; font-size: 12px; }
.param .name { grid-column: 1 / 3; color: var(--dim); }
.param .slide { position: relative; }
.param input[type=range] { width: 100%; display: block; }
.param .ours { display: none; position: absolute; top: -3px; bottom: -3px; width: 9px; padding: 0; border: 0; background: none; cursor: pointer;
  left: calc(8px + (100% - 16px) * var(--at) - 4.5px); }
.param .ours::after { content: ""; position: absolute; left: 3.5px; top: 0; bottom: 0; width: 2px; border-radius: 1px; background: var(--warn); }
.param.changed .ours { display: block; }
.param.changed .name { color: var(--warn); }
.param input[type=number] { width: 76px; padding: 2px 6px; background: var(--panel); }
.param.bool { grid-template-columns: 1fr auto; }
.param.bool .name { grid-column: 1; }
.param.text input { grid-column: 1 / 3; padding: 2px 6px; background: var(--panel); }
.help { display: inline-flex; align-items: center; justify-content: center; width: 14px; height: 14px; margin-left: 2px; border-radius: 50%;
  border: 1px solid var(--dim); color: var(--dim); font-size: 10px; font-weight: 700; line-height: 1; cursor: help; vertical-align: 1px; }
.help:hover, .help:focus-visible { color: var(--accent); border-color: var(--accent); outline: none; }
#finder-note { margin: 8px 0 0; }

#view { position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0; margin: var(--pad) 0;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-panel); overflow: hidden; }
.toolbar { display: flex; gap: 10px; align-items: center; height: 52px; padding: 0 var(--pad); border-bottom: 1px solid var(--line); font-size: 13px; }
.toolbar .group { display: flex; gap: 10px; align-items: center; }
.toolbar .grow { flex: 1; }
button.big { padding: 6px 18px; font-size: 14px; font-weight: 600; background: var(--accent); border-color: var(--accent); color: #fff; }
#image-view, #items-view { flex: 1; min-height: 0; display: flex; flex-direction: column; }
#image-view[hidden], #items-view[hidden] { display: none; }
#items-view { overflow-y: auto; padding: var(--pad); }
/* zoom: one rounded segmented control */
.zoom { display: inline-flex; align-items: stretch; border: 1px solid var(--line); border-radius: var(--r-ctl); overflow: hidden; background: var(--panel); }
.zoom button { border: 0; border-radius: 0; background: transparent; width: 32px; font-size: 16px; line-height: 1; padding: 5px 0; }
.zoom button:hover { background: var(--bg); }
#zoom-label { min-width: 44px; text-align: center; align-self: center; font-variant-numeric: tabular-nums; border-left: 1px solid var(--line); border-right: 1px solid var(--line); padding: 5px 0; }
/* the overlay options, folded into one dropdown */
.menu { position: relative; }
.menu summary { list-style: none; cursor: pointer; padding: 5px 12px; border: 1px solid var(--line); border-radius: var(--r-ctl); background: var(--panel); }
.menu summary::-webkit-details-marker { display: none; }
.menu summary::after { content: " ▾"; color: var(--dim); }
.menu .pop { position: absolute; top: calc(100% + 4px); left: 0; z-index: 20; display: flex; flex-direction: column; gap: 8px; min-width: 170px;
  padding: 10px 14px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-ctl); box-shadow: 0 6px 18px #0004; }
.menu .pop label { display: flex; align-items: center; gap: 6px; white-space: nowrap; }
.menu .opt { display: flex; align-items: center; gap: 8px; }
.menu .opt label { flex: 1; }
.menu .opt input[type=range] { width: 80px; }
.menu .opt input[type=color] { width: 26px; height: 22px; padding: 0 2px; }
.menu .pop label.num input { width: 58px; padding: 2px 6px; }
/* each view shows only its own tools */
#view[data-view=image] .for-items, #view[data-view=items] .for-image { display: none; }
.tabs { display: inline-flex; border: 1px solid var(--line); border-radius: var(--r-ctl); overflow: hidden; }
.tabs button { border: 0; border-radius: 0; background: transparent; padding: 5px 14px; }
.tabs button + button { border-left: 1px solid var(--line); }
.tabs button.on { background: var(--accent); color: #fff; }
.tabs span { opacity: .75; font-variant-numeric: tabular-nums; }
button.icon { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px; padding: 0; border-radius: 50%; }
button.icon svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
/* the theme button shows where it goes: a sun in dark mode, a moon in light */
#theme .moon, :root[data-theme=light] #theme .sun { display: none; }
:root[data-theme=light] #theme .moon { display: inline; }
@media (prefers-color-scheme: light) {
  :root:not([data-theme]) #theme .sun { display: none; }
  :root:not([data-theme]) #theme .moon { display: inline; }
}
#scroller { flex: 1; overflow: auto; position: relative; background: var(--bg); cursor: grab; touch-action: none; }
#scroller.dragging, #scroller.dragging #overlay g[data-i] { cursor: grabbing; }
#empty { color: var(--dim); padding: 40px; text-align: center; }
#stage { position: relative; }
#base { image-rendering: pixelated; display: block; }
#overlay { position: absolute; left: 0; top: 0; }
#overlay { --pass-c: var(--pink); --fail-c: var(--blue); --pass-w: 1px; --fail-w: 1px; }
#overlay path { fill: none; vector-effect: non-scaling-stroke; stroke-opacity: .6; }
#overlay .red { stroke-opacity: .45; }
#overlay .pass path { stroke: var(--pass-c); stroke-width: var(--pass-w); }
#overlay .fail path { stroke: var(--fail-c); stroke-width: var(--fail-w); }
#overlay .pass .num { fill: var(--pass-c); }
#overlay .fail .num { fill: var(--fail-c); }
#overlay.no-pass .pass, #overlay.no-fails .fail, #overlay.no-nums .num, #overlay.no-letters .let { display: none; }
/* the selection: a thin white ring, clear of the markings */
#overlay .ring { fill: none; stroke: #fff; stroke-opacity: .9; stroke-width: 1.25; vector-effect: non-scaling-stroke; pointer-events: none; }
#overlay .lines { display: none; }
#overlay .pass .lines { display: inline; }
#overlay.no-lines .pass .lines { display: none; }
#overlay .lines line { stroke: #fff; vector-effect: non-scaling-stroke; stroke-width: 1; }
#overlay .lines line.r { stroke-width: 2; }
#overlay text { paint-order: stroke; stroke: #000; stroke-width: 2px; stroke-opacity: .6; font-family: system-ui, sans-serif; }
#overlay .hit { fill: transparent; cursor: pointer; }
#overlay g[data-i] { cursor: pointer; }
#overlay .forced path { stroke-dasharray: 2 1; stroke-opacity: 1; }
#overlay .red, #overlay .lines { pointer-events: none; }

#list { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: var(--pad); align-items: start; }
.card { background: var(--bg); border: 1px solid var(--line); border-radius: var(--r-ctl); padding: 10px; font-size: 12px; }
.card .crop { position: relative; width: max-content; max-width: 100%; margin: 0 auto 8px; line-height: 0; }
/* a crop narrower than its box shrinks as a whole: its height follows its width */
.card .crop canvas { display: block; image-rendering: pixelated; border-radius: var(--r-chip); max-width: 100%; height: auto; }
.card .marks { position: absolute; left: 0; top: 0; width: 100%; height: 100%; overflow: visible; }
.card .marks line { stroke: #fff; stroke-width: 1; vector-effect: non-scaling-stroke; }
.card .marks line.r { stroke-width: 2.5; }
.card .marks text { fill: #fff; text-anchor: middle; paint-order: stroke; stroke: #000; font-family: system-ui, sans-serif; }
.card .marks text.r { fill: #ffb3b3; }
.card .marks .handle { fill: #fff; stroke: #000; cursor: ew-resize; }
.card .marks .handle.r { fill: #ff6b6b; }
.card .head { display: flex; gap: 6px; align-items: center; margin-bottom: 8px; }
/* the user's verdict: a thumbs up and a thumbs down side by side, quiet until pointed at or chosen */
.card .verdict { margin-left: auto; display: inline-flex; flex: none; border: 1px solid var(--line); border-radius: 999px; overflow: hidden; background: var(--panel); }
.card .verdict button { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 26px; padding: 0;
  border: 0; border-radius: 0; background: transparent; color: var(--dim); transition: background .12s, color .12s; }
.card .verdict button + button { border-left: 1px solid var(--line); }
/* the thumb icon, on the cards and beside each filter's count; the filters' is a thumbs down */
.card .verdict svg, .filter .n svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.card .verdict .down svg, .filter .n svg { transform: rotate(180deg) scaleX(-1); }
.card .verdict .up:hover { color: var(--yes); background: color-mix(in srgb, var(--yes) 14%, transparent); }
.card .verdict .down:hover { color: var(--no); background: color-mix(in srgb, var(--no) 14%, transparent); }
.card .verdict .up.on { color: #fff; background: var(--yes); }
.card .verdict .down.on { color: #fff; background: var(--no); }
.card .verdict button.on svg { fill: #ffffff40; }
/* the go-to button sits on the crop, faint until the pointer is over it */
.card .crop-wrap { position: relative; width: max-content; max-width: 100%; margin: 0 auto 8px; }
.card .crop-wrap .crop { margin: 0; }
.card .goto { position: absolute; top: 5px; right: 5px; width: 26px; height: 26px; padding: 0; display: inline-flex; align-items: center; justify-content: center;
  border-radius: 50%; border: 1px solid #ffffff60; background: #000000a0; color: #fff; opacity: .3; transition: opacity .15s; }
.card .crop-wrap:hover .goto, .card .goto:focus-visible { opacity: 1; }
.card .goto:hover { background: var(--accent); border-color: var(--accent); }
.card .goto svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
.card .goto svg .dot { fill: currentColor; stroke: none; }
.card .num { font-weight: 700; }
.card.pass .num { color: var(--pink); } .card.fail .num { color: var(--blue); }
.card .state { color: var(--dim); min-width: 0; }
/* the selected candidate's card in the item views */
.card { cursor: pointer; scroll-margin: var(--pad); }
#selected .card { cursor: default; }
.card.selected { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent), 0 0 14px color-mix(in srgb, var(--accent) 45%, transparent); }
.card .tag { color: var(--warn); margin: -2px 0 4px; }
.card .why { display: flex; flex-wrap: wrap; gap: 4px 10px; margin: 2px 0 6px; }
.card.approved { border-color: var(--yes); }
.card.byyou { border-color: var(--no); }
.card .tag button { font-size: 12px; margin-left: 6px; }
.card button { padding: 2px 8px; font-size: 11px; border-radius: var(--r-chip); }
.card table { width: 100%; border-collapse: collapse; }
.card td:last-child { text-align: right; font-variant-numeric: tabular-nums; }
.card td { color: var(--dim); } .card td:last-child { color: var(--text); }

#selected .card { background: var(--bg); }
.stepper { display: inline-flex; border: 1px solid var(--line); border-radius: var(--r-ctl); overflow: hidden; }
.stepper button { border: 0; border-radius: 0; background: transparent; width: 32px; padding: 2px 0; font-size: 16px; line-height: 1.2; }
.stepper button + button { border-left: 1px solid var(--line); }
.stepper button:not(:disabled):hover { background: var(--bg); }
#selected-box .sec-head { margin-bottom: 10px; }
#downloads { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
#downloads h2 { flex-basis: 100%; margin-bottom: 2px; }
#summary .tbl { overflow-x: auto; }
#summary table { border-collapse: collapse; margin-top: 8px; font-variant-numeric: tabular-nums; font-size: 12px; width: 100%; }
#summary th, #summary td { padding: 4px 4px; text-align: right; border-bottom: 1px solid var(--line); }
#summary th:first-child, #summary td:first-child { text-align: left; }
#summary .hists { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 12px; }
#summary .hist { font-size: 12px; color: var(--dim); }
#summary .hist rect { fill: var(--pink); opacity: .75; }
#summary .reasons { margin-top: 12px; color: var(--dim); font-size: 13px; }

/* the footer: file, counts and timings as sections on the left; progress and the version on the right */
#statusbar { display: flex; align-items: center; gap: 10px; height: 1cm; padding: 0 14px; background: var(--panel); border-top: 1px solid var(--line);
  font-size: 12px; color: var(--dim); white-space: nowrap; overflow: hidden; }
#statusbar .seg { padding-right: 10px; border-right: 1px solid var(--line); }
#statusbar .seg:empty { display: none; }
#statusbar .grow { flex: 1; }
#statusbar b { color: var(--text); font-weight: 600; font-variant-numeric: tabular-nums; }
#sb-file { color: var(--text); font-weight: 600; max-width: 30vw; overflow: hidden; text-overflow: ellipsis; }
#sb-times { font-variant-numeric: tabular-nums; }
#status { overflow: hidden; text-overflow: ellipsis; min-width: 0; }
#status.err { color: var(--err); }
#statusbar .spin { width: 12px; height: 12px; display: none; }
#statusbar .spin.on { display: inline-block; }
#sb-version { padding: 1px 8px; border: 1px solid var(--line); border-radius: var(--r-chip); font-variant-numeric: tabular-nums; }
#sb-version.stale { cursor: pointer; color: var(--bg); background: var(--warn); border-color: var(--warn); font-weight: 600; }

#tip { position: fixed; pointer-events: none; background: var(--tipbg); color: var(--text); border: 1px solid var(--line); border-radius: var(--r-ctl); padding: 8px 10px; font-size: 12px; max-width: 320px; z-index: 10; white-space: pre-line; }

@media (max-width: 1300px) {
  #layout { --lw: 260px; --rw: 300px; }
}

.spin { display: inline-block; width: 14px; height: 14px; border: 2px solid var(--line); border-top-color: var(--pink); border-radius: 50%; animation: spin .8s linear infinite; visibility: hidden; }
.spin.on { visibility: visible; }
.spin.big { width: 44px; height: 44px; border-width: 4px; visibility: visible; }
@keyframes spin { to { transform: rotate(360deg); } }
#busy { position: absolute; inset: 52px 0 0 0; z-index: 5; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; background: var(--shade); color: var(--text); }
#busy[hidden] { display: none; }
#busy-time { color: var(--dim); font-variant-numeric: tabular-nums; }
/* over an image (Find Candidates, or one painting as it downloads) the text sits in a pill below it, and
   Find Candidates sweeps a copier's light bar back and forth over the image */
#scan-light { display: none; }
#busy.scan, #busy.peek { background: none; justify-content: flex-end; padding-bottom: 28px; pointer-events: none; overflow: hidden; }
#busy.scan .spin.big, #busy.peek .spin.big { display: none; }
#busy.scan #busy-text, #busy.scan #busy-time, #busy.peek #busy-text, #busy.peek #busy-time { position: relative; z-index: 1; }
#busy.scan #busy-text, #busy.peek #busy-text { padding: 5px 14px; border-radius: 999px; background: var(--shade); font-weight: 600; font-variant-numeric: tabular-nums; }
#busy.scan #busy-time, #busy.peek #busy-time { margin-top: -6px; padding: 1px 10px; border-radius: 999px; background: var(--shade); color: var(--text); }
#busy.scan #scan-light { display: block; position: absolute; top: 0; bottom: 0; left: -90px; width: 90px; mix-blend-mode: screen;
  background: linear-gradient(90deg, transparent, rgba(150, 255, 190, .10) 30%, rgba(235, 255, 245, .75) 50%, rgba(150, 255, 190, .10) 70%, transparent);
  box-shadow: 0 0 60px 20px rgba(120, 255, 170, .18); animation: copier 2.4s ease-in-out infinite alternate; }
@keyframes copier { from { transform: translateX(0); } to { transform: translateX(calc(100cqw + 90px)); } }
#busy.scan { container-type: inline-size; }
@media (prefers-reduced-motion: reduce) { #busy.scan #scan-light { animation-duration: 8s; } }

/* the Google Drive dialog */
#drive-dlg { width: min(640px, calc(100vw - 32px)); padding: 18px; color: var(--text); background: var(--panel);
  border: 1px solid var(--line); border-radius: var(--r-panel); box-shadow: 0 12px 40px #0006; }
#drive-dlg::backdrop { background: #0007; }
.drive-row { display: flex; gap: 8px; align-items: center; margin-top: 10px; }
.drive-row.end { justify-content: space-between; }
#drive-link { flex: 1; min-width: 0; }
/* every part keeps its size whatever the folder holds, so the dialog stays still while browsing */
#drive-path { margin-top: 10px; font-size: 13px; height: 1.5em; line-height: 1.5em; white-space: nowrap; overflow-x: auto; overflow-y: hidden; }
#drive-list { display: flex; flex-direction: column; height: 300px; overflow-y: auto; margin-top: 6px;
  border: 1px solid var(--line); border-radius: var(--r-ctl); }
#drive-list .item { display: flex; gap: 12px; align-items: baseline; flex: none; text-align: left; border: 0; border-radius: 0; background: none; padding: 6px 10px; }
#drive-list .item .name { flex: 1; min-width: 0; overflow-wrap: anywhere; }
#drive-list .item .meta { color: var(--dim); font-size: 12px; white-space: nowrap; font-variant-numeric: tabular-nums; }
#drive-msg { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#drive-list .item + .item { border-top: 1px solid var(--line); }
#drive-list .item:hover { background: var(--bg); }
#drive-list .item.folder .name::before { content: "📁 "; }
#drive-msg.err { color: var(--err); }

/* a box that folds: its title opens and closes it */
.box.foldable > .sec-head h2 { display: flex; align-items: center; gap: 7px; cursor: pointer; user-select: none; }
.box.foldable.folded > :not(.sec-head) { display: none; }
.box.foldable.folded > .sec-head button { display: none; }

/* missing candidates: the user's marks where the finder proposed nothing, in a colour the image never has */
#overlay .missing-marks { --miss: #ffd400; pointer-events: none; }
#overlay .missing-marks circle { fill: none; stroke: var(--miss); stroke-width: 1.5; stroke-dasharray: 4 3; vector-effect: non-scaling-stroke; }
#overlay .missing-marks text { fill: var(--miss); }
.card.missing { border-color: #ffd40080; }
.card .verdict .remove { font-size: 18px; line-height: 1; color: var(--dim); }
.card .verdict .remove:hover { color: var(--no); background: color-mix(in srgb, var(--no) 14%, transparent); }
#ctx { position: fixed; z-index: 30; display: flex; flex-direction: column; padding: 4px 8px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-ctl); box-shadow: 0 6px 18px #0006; }
#ctx .item { text-align: left; border: 0; background: none; padding: 6px 4px; white-space: nowrap; }
#ctx .item:hover, #ctx .item:focus-visible { color: var(--accent); }
#notice { position: fixed; z-index: 40; max-width: min(360px, calc(100vw - 16px)); background: var(--panel); color: var(--text); border: 1px solid var(--accent);
  border-radius: var(--r-ctl); padding: 12px 14px; box-shadow: 0 8px 24px #0007; display: flex; flex-direction: column; gap: 10px; font-size: 13px; }
#notice[hidden] { display: none; }
#notice p { margin: 0; }
#notice button { align-self: flex-end; }
#ctx[hidden], #card-menu[hidden] { display: none; }

